Q: Laravel pagination without refreshing page A: <pre><code>&lt;!-- I used rows instead of tables and it works. --&gt;




&lt;!-- welcome blade --&gt;

&lt;div id=&quot;movie_table&quot; class=&quot;row justify-content-center&quot; data-aos=&quot;fade-up&quot; data-aos-delay=&quot;200&quot;&gt;

   @include('paginations/moviepagination')

&lt;/div&gt;

&lt;script src=&quot;https://ajax.googleapis.com/ajax/libs/jquery/3.1.0/jquery.min.js&quot;&gt;&lt;/script&gt;
&lt;script&gt;
    $(document).ready(function(){
        $(document).on('click', '.pagination a', function(event){
            event.preventDefault(); 
            var page = $(this).attr('href').split('page=')[1];
            fetch_user_data(page);
        });

        function fetch_user_data(page)
        {

            $.ajax({
                url:&quot;/xxx/pagination?page=&quot;+page,
                success:function(data)
                {
                    $('#movie_table').html(&quot;&quot;);
                    $('#movie_table').html(data);
                }
            });
        }    
    });
&lt;/script&gt;




&lt;!-- pagination blade --&gt;

@foreach($entertainments as $entertaints)


&lt;div class=&quot;col-lg-3 col-md-6 &quot; style=&quot; padding: 5px;&quot;&gt;
     &lt;div class=&quot;&quot;&gt;&lt;a href=&quot;https://{{$entertaints-&gt;website}}&quot;&gt;&lt;img src=&quot;{{$entertaints-  &gt;poster}}&quot; style=&quot;width: 100%;&quot; class=&quot;img-fluid&quot; alt=&quot;&quot;&gt;&lt;/a&gt;&lt;/div&gt;

&lt;/div&gt;


@endforeach  


